describe('Reorder List Items by Drag and Drop', () => {
    beforeEach(() => {
        cy.visit('/your-page-url'); // Replace with your actual page URL
    });

    it('should successfully reorder list items using drag and drop', () => {
        const itemToDrag = 'Item 1'; // Replace with the actual item text
        const targetPosition = 'Item 3'; // Replace with the actual target item text

        cy.get('.list-item') // Replace with the actual selector for list items
            .contains(itemToDrag)
            .trigger('mousedown', { which: 1 });

        cy.get('.list-item') // Replace with the actual selector for list items
            .contains(targetPosition)
            .trigger('mousemove')
            .trigger('mouseup', { force: true });

        cy.get('.list-item') // Replace with the actual selector for list items
            .eq(1) // Assuming the item is moved to the second position
            .should('contain', itemToDrag);
    });

    it('should not reorder list items if drag is canceled', () => {
        const itemToDrag = 'Item 2'; // Replace with the actual item text
        const originalPosition = 1; // Assuming original position is 1

        cy.get('.list-item') // Replace with the actual selector for list items
            .contains(itemToDrag)
            .trigger('mousedown', { which: 1 });

        cy.get('body').trigger('mouseup'); // Cancel the drag

        cy.get('.list-item') // Replace with the actual selector for list items
            .eq(originalPosition)
            .should('contain', itemToDrag); // Verify it remains in the original position
    });
});
